(* [comment removed for export] *)
Definition srccls (a : Z) : Prop :=
  in_block LB a \/ (hl_img_lo L <= a < hl_img_hi L /\ ~ hl_rt_static L a) \/ in_fframe FF a
  \/ (exists f, In f FF /\ in_shadow_of (ff_addr f) (ff_bytes (ff_class f)) a) \/ (exists b, In b LB /\ in_shadow_of (fst b) (snd b) a).
Lemma srccls_client a sp scr : srccls a -> ~ (sp - scr <= a < sp) -> aclient L ar LB FF sp scr a.
Proof.
