Lemma src_xfer (M M' : word -> option byte) LB' LK cr Aw V :
  PQASA.src_okA RSEGS L HI M LB FF qs n -> ri_inv HI LB' FF LK cr Aw M' V ->
  (forall a, 0 <= a < 2 ^ 64 -> srccls a -> (qs <= a < qs + n \/ in_shadow_of qs n a) -> M' (Z_to_bv 64 a) = M (Z_to_bv 64 a)) ->
  PQASA.src_okA RSEGS L HI M' LB FF qs n.
