Ltac Zify.zify_convert_to_euclidean_division_equations_flag ::= constr:(true).
Lemma blk_sh0_vis LB' LK cr Aw M model b m a :
  ri_inv HI LB' FF LK cr Aw M (vml_of model) -> In (b, m) LB' -> PMSPA.accA M b m -> b mod 8 = 0 -> m mod 8 = 0 -> b <= a < b + m ->
