  0 <= a0 < 2 ^ 64 -> kept0 R -> saves M -> mem_ok M ->
  ri_inv HI (PM.vs_own x' ++ LB) FF LK cr' Aw M (vml_of model) ->
  srealizes RSEGS SCFG (@PMSPA.cfg RSEGS fx R 0xb9c18 M model) K.
