Lemma back_gb (fx : FPState) R M model LK Aw (B a0 : Z) (cr' : credit) :
  stok model LK Aw -> PM.vs_cap x < need ->
  L5.defined M o 24 -> PMSPA.accA M o 24 -> L5.u64_at RSEGS M o (GA + 1) -> L5.u64_at RSEGS M (o + 16) B ->
  L5.defined M B GA -> PMSPA.accA M B GA -> L5.bytes_at RSEGS M B kbs -> PQMA.ks_ok SM (PM.VLong GA need B) (g + 1) -> need < GA -> 26 <= GA <= PQMA.KCAP -> GA mod 8 = 0 ->
  PMSP.credit_keep cr0 cr' (scA (PQMA.pot_ks HV SM x g)) (scA (PQMA.pot_ks HV SM (PM.VLong GA need B) (g + 1))) ->
  getr R (reg 2) = Z_to_bv 64 (S - 80) -> getr R (reg 4) = Z_to_bv 64 (hl_tp L) -> getr R (reg 8) = Z_to_bv 64 (PM.vs_size x) -> getr R (reg 9) = Z_to_bv 64 o ->
  getr R (reg 10) = Z_to_bv 64 a0 -> getr R (reg 18) = Z_to_bv 64 qs -> getr R (reg 19) = Z_to_bv 64 (qs + n) -> getr R (reg 20) = Z_to_bv 64 n ->
  getr R (reg 21) = Z_to_bv 64 (PM.vs_size x) -> getr R (reg 22) = Z_to_bv 64 2147450880 -> getr R (reg 23) = Z_to_bv 64 (o / 8 + 2147450880) ->
  getr R (reg 24) = Z_to_bv 64 need ->
  0 <= a0 < 2 ^ 64 -> kept0 R -> saves M -> mem_ok M -> srcB M ->
  ri_inv HI ((B, GA) :: LB) FF LK cr' Aw M (vml_of model) ->
